# Shared helpers for the characterization baseline (test-characterization-*.R).
#
# The characterization tests pin the 0.1.5 behaviour of richR on small
# committed fixtures (tests/testthat/fixtures/, regenerated by
# fixtures/make-fixtures.R). Every pinned value is recorded with
# expect_snapshot_value() / expect_snapshot(); a later change shows up as a
# snapshot diff instead of silent drift.

# Read a fixture CSV. `character = TRUE` keeps identifiers such as KEGG map
# ids ("00010") from being coerced to numbers.
.char_read <- function(name, character = FALSE) {
  utils::read.csv(
    testthat::test_path("fixtures", name), stringsAsFactors = FALSE,
    colClasses = if (character) "character" else NA
  )
}

# A pinned data.frame must be non-empty (a green with nothing swept asserts
# nothing). Returns the data.frame unchanged: snapshots use style = "deparse",
# which records column order, row names, classes, and values at 15 significant
# digits (json2 only round-trips ~8 digits, too coarse for the 1e-8 tolerance).
.char_pin_df <- function(df) {
  stopifnot(is.data.frame(df), nrow(df) > 0L)
  df
}

# Characterization tests must never pin an empty sweep (a green with nothing
# swept asserts nothing). Returns the data.frame so calls can be piped through.
.char_nonempty <- function(df) {
  testthat::expect_gt(nrow(df), 0L)
  df
}

# Every slot of an S4 result object other than its data.frame slots (those are
# pinned separately with .char_pin_df()), as a named list.
.char_slots <- function(x) {
  nm <- setdiff(methods::slotNames(x), c("result", "detail", "annot", "tested"))
  stats::setNames(lapply(nm, function(s) methods::slot(x, s)), nm)
}

# The exact-numeric GSEA snapshots (characterization-gsea.md and the compareGSEA
# curve in characterization-compare.md) were recorded with this fgsea version,
# which each snapshot also carries under the key `fgsea_version`. fgsea's
# permutation and curve code may change between releases, so those snapshots
# run only on the recorded version and are skipped, with the message below,
# on any other; version-independent invariants run everywhere fgsea is installed.
.char_fgsea_recorded <- "1.38.0"

.char_skip_unless_recorded_fgsea <- function() {
  testthat::skip_if_not_installed("fgsea")
  have <- as.character(utils::packageVersion("fgsea"))
  testthat::skip_if_not(
    identical(have, .char_fgsea_recorded),
    sprintf(
      "exact-numeric GSEA snapshots were recorded with fgsea %s; installed fgsea is %s",
      .char_fgsea_recorded, have
    )
  )
}

# ---- hand-built objects (no analysis involved) -------------------------------

.char_richResult <- function() {
  methods::new(
    "richResult",
    result = data.frame(
      Annot = c("GO:0001", "GO:0002", "GO:0003"),
      Term = c("apoptosis", "cell cycle", "signaling"),
      Annotated = c(100, 200, 50),
      Significant = c(10, 20, 5),
      RichFactor = c(0.1, 0.1, 0.1),
      FoldEnrichment = c(2.5, 2, 1.5),
      zscore = c(3.5, 3, 2.5),
      Pvalue = c(0.001, 0.01, 0.04),
      Padj = c(0.01, 0.05, 0.08),
      GeneID = c("A,B,C", "D,E,F,G", "A,H"),
      stringsAsFactors = FALSE,
      row.names = c("GO:0001", "GO:0002", "GO:0003")
    ),
    detail = data.frame(
      TERM = c("GO:0001", "GO:0001", "GO:0002"),
      Annot = c("apoptosis", "apoptosis", "cell cycle"),
      GeneID = c("A", "B", "D"),
      Pvalue = c(0.001, 0.001, 0.01),
      Padj = c(0.01, 0.01, 0.05),
      stringsAsFactors = FALSE
    ),
    pvalueCutoff = 0.05,
    pAdjustMethod = "BH",
    padjCutoff = numeric(),
    genenumber = 10,
    organism = "human",
    ontology = "BP",
    gene = LETTERS[1:10],
    keytype = "SYMBOL",
    sep = ","
  )
}

